106	        this.city = city;
107	    }
108	
109	    /**
110	     * The owner's locality, i.e. the canonical region it belongs to (read from the
111	     * assigned {@link #customerCode} when present, otherwise derived from the owner's
112	     * own fields via {@link #regionForOwner()}). Derived (not persisted); recomputed
113	     * each call. See {@link OwnerDerivations#locality(String, String, String)} for the
114	     * full derivation.
115	     *
116	     * @return the canonical region string, or {@code "UNKNOWN"}
117	     */
118	    @Transient
119	    public String getLocality() {
120	        return OwnerDerivations.locality(this.customerCode, this.postcode, this.city);
121	    }
