133	    /**
134	     * The owner's IANA timezone name, derived from its {@link #getLocality() locality}
135	     * (canonical region) via the fixed region-to-timezone table. Derived (not persisted);
136	     * recomputed each call and {@code null} when the locality is not a known region. See
137	     * {@link OwnerDerivations#timezone(String)} for the derivation.
138	     *
139	     * @return the IANA timezone name, or {@code null}
140	     */
141	    @Transient
142	    public String getTimezone() {
143	        return OwnerDerivations.timezone(this.getLocality());
144	    }
145	
146	    /**
147	     * Whether this owner's postcode is consistent with its {@link #getLocality()
148	     * locality}: an absent postcode is accepted, a present one must be exactly four
149	     * digits and, when the locality has a known postcode range, fall within it. See
150	     * {@link OwnerDerivations#postcodeMatchesRegion(String, String)}.
151	     *
152	     * @return {@code true} if the postcode is absent or valid for the owner's locality
153	     */
154	    public boolean postcodeValidForLocality() {
155	        return OwnerDerivations.postcodeMatchesRegion(this.postcode, this.getLocality());
156	    }
157	
158	    /**
159	     * The owner's membership points, a non-negative score derived from its factors.
160	     * Derived (not persisted); recomputed from the current fields each call, so it rises
161	     * once the owner's tenure since {@link #registrationDate} exceeds 365 days. See
162	     * {@link OwnerDerivations#membershipPoints(String, Integer, Integer, LocalDate, LocalDate)}
163	     * for how it is scored.
164	     *
165	     * @return the membership points, 0 or more
166	     */
167	    @Transient
168	    public Integer getMembershipPoints() {
169	        return OwnerDerivations.membershipPoints(this.email, this.namesakeCount, this.householdSize,
170	            this.registrationDate, LocalDate.now());
171	    }
172	
173	    /**
174	     * The owner's membership level, a number from 1 to 4, mapped from its
175	     * {@link #getMembershipPoints() membership points}. Derived (not persisted);
176	     * recomputed from the current fields each call, so it rises to level 4 once the
177	     * owner's tenure since {@link #registrationDate} exceeds 365 days. See
178	     * {@link OwnerDerivations#membershipLevel(int)} for the mapping.
179	     *
180	     * @return the membership level, from 1 to 4
181	     */
182	    @Transient
183	    public Integer getMembershipLevel() {
