187	    /**
188	     * The owner's preferred contact channel, {@code "EMAIL"} or {@code "PHONE"}.
189	     * Derived (not persisted); recomputed from the current fields each call. See
190	     * {@link OwnerDerivations#contactPreference(String)}.
191	     *
192	     * @return {@code "EMAIL"} or {@code "PHONE"}
193	     */
194	    @Transient
