200	        return this.telephone;
201	    }
202	
203	    /**
204	     * The stored E.164 {@link #telephone} formatted for humans: a leading '+'
205	     * and country code, a space, then the national digits grouped in threes
206	     * (e.g. {@code "+61 412 345 678"}). Derived (not persisted); recomputed each
207	     * call and {@code null} when no telephone is present. See
208	     * {@link Telephones#toDisplay(String)} for the exact format.
209	     *
210	     * @return the human-formatted telephone, or {@code null} when absent
211	     */
212	    @Transient
213	    public String getTelephoneDisplay() {
