219	    }
220	
221	    public String getEmail() {
222	        return this.email;
223	    }
224	
225	    public void setEmail(String email) {
226	        this.email = email;
227	    }
228	
229	    public String getPostcode() {
230	        return this.postcode;
231	    }
232	
233	    public void setPostcode(String postcode) {
234	        this.postcode = postcode;
235	    }
236	
237	    public LocalDate getRegistrationDate() {
238	        return this.registrationDate;
239	    }
240	
241	    public void setRegistrationDate(LocalDate registrationDate) {
242	        this.registrationDate = registrationDate;
243	    }
244	
245	    public LocalDate getBirthDate() {
246	        return this.birthDate;
247	    }
248	
249	    public void setBirthDate(LocalDate birthDate) {
250	        this.birthDate = birthDate;
251	    }
252	
253	    /**
254	     * The owner's age band, {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"},
255	     * derived from {@link #birthDate} measured against {@link #registrationDate}.
256	     * Derived (not persisted); recomputed each call and {@code null} when no birth
257	     * date has been supplied. See
258	     * {@link OwnerDerivations#ageBand(LocalDate, LocalDate)} for the derivation.
259	     *
260	     * @return the age band, or {@code null} when no birth date is present
261	     */
262	    @Transient
263	    public String getAgeBand() {
264	        return OwnerDerivations.ageBand(this.birthDate, this.registrationDate);
265	    }
266	
267	    public String getCustomerCode() {
268	        return this.customerCode;
269	    }
270	
271	    public void setCustomerCode(String customerCode) {
272	        this.customerCode = customerCode;
273	    }
274	
275	    /**
276	     * The Luhn check digit (0-9) computed over the digits in this owner's
277	     * {@link #customerCode}. Derived (not persisted); recomputed each call. See
278	     * {@link OwnerDerivations#checkDigit(String)}.
279	     *
280	     * @return the Luhn check digit, from 0 to 9
281	     */
282	    @Transient
283	    public Integer getCheckDigit() {
284	        return OwnerDerivations.checkDigit(this.customerCode);
285	    }
286	
287	    public String getHouseholdId() {
288	        return this.householdId;
289	    }
290	
291	    public void setHouseholdId(String householdId) {
292	        this.householdId = householdId;
293	    }
294	
295	    public Integer getNamesakeCount() {
296	        return this.namesakeCount;
297	    }
298	
299	    public void setNamesakeCount(Integer namesakeCount) {
300	        this.namesakeCount = namesakeCount;
301	    }
302	
303	    public String getMembershipNumber() {
304	        return this.membershipNumber;
305	    }
306	
307	    public void setMembershipNumber(String membershipNumber) {
308	        this.membershipNumber = membershipNumber;
309	    }
310	
311	    public Boolean getBulkSignupWarning() {
312	        return this.bulkSignupWarning;
313	    }
314	
315	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
316	        this.bulkSignupWarning = bulkSignupWarning;
317	    }
318	
319	    public Integer getHouseholdSize() {
320	        return this.householdSize;
321	    }
322	
323	    public void setHouseholdSize(Integer householdSize) {
324	        this.householdSize = householdSize;
325	    }
326	
327	    public Boolean getPossibleDuplicate() {
328	        return this.possibleDuplicate;
329	    }
330	
331	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
332	        this.possibleDuplicate = possibleDuplicate;
333	    }
334	
335	    public Integer getPossibleDuplicateOf() {
336	        return this.possibleDuplicateOf;
337	    }
338	
339	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
340	        this.possibleDuplicateOf = possibleDuplicateOf;
341	    }
342	
343	    /**
344	     * The derived key used for duplicate detection, combining this owner's normalised
345	     * telephone, email and {@link #householdId}. Two owners are duplicates exactly when
346	     * their whole identity keys are equal, so members of the same household with
347	     * different telephones have different keys. Derived (not persisted); recomputed each
348	     * call. See {@link OwnerDerivations#identityKey(String, String, String)} for the
349	     * exact format.
350	     *
351	     * @return the owner's identity key
352	     */
353	    @Transient
354	    public String getIdentityKey() {
355	        return OwnerDerivations.identityKey(this.telephone, this.email, this.householdId);
356	    }
357	
358	    /**
359	     * Compute the customer code to assign to this owner at creation, formatted
360	     * {@code <REGION>-<HASH8>} from the owner's (already normalised) fields. This is the
361	     * value stored in {@link #getCustomerCode()}; see
362	     * {@link OwnerDerivations#customerCode(String, String, String)} for the format.
363	     *
364	     * @return the customer code to assign
365	     */
366	    public String computeCustomerCode() {
367	        return OwnerDerivations.customerCode(regionForOwner(), this.telephone, this.getLastName());
368	    }
369	
370	    /**
371	     * Compute the stable household identifier for this owner, derived deterministically
372	     * from its last name and postcode so every owner sharing a last name and postcode
373	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
374	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
375	     *
376	     * @return the household identifier
377	     */
378	    public String computeHouseholdId() {
379	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
380	    }
381	
382	    /**
383	     * Whether this owner belongs to the same household as {@code other}: that is, they
384	     * share the same last name and postcode. The last name is compared
385	     * case-insensitively with runs of whitespace collapsed to a single space (and
386	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
387	     * absent postcodes count as equal). Owners in the same household resolve to the same
388	     * {@link #computeHouseholdId() household identifier}.
389	     *
390	     * @param other the owner to compare against
391	     * @return {@code true} if both owners share a household
392	     */
393	    public boolean sameHouseholdAs(Owner other) {
394	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
395	            && Objects.equals(this.postcode, other.postcode);
396	    }
397	
398	    /**
399	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
400	     * trim, collapse internal runs of whitespace to a single space and lower-case.
401	     */
402	    private static String normalize(String value) {
403	        if (value == null) {
404	            return "";
405	        }
406	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
407	    }
408	
409	    /**
410	     * Reduce an address to its canonical stored form. This is the value stored,
411	     * returned and used for every household comparison; see
412	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
413	     *
414	     * @param value the raw address (may be {@code null})
415	     * @return the normalised address, or the empty string if {@code value} is
416	     *         {@code null} or blank
417	     */
418	    public static String normalizeAddress(String value) {
419	        return OwnerDerivations.normalizeAddress(value);
420	    }
421	
422	    protected Set<Pet> getPetsInternal() {
423	        if (this.pets == null) {
424	            this.pets = new HashSet<>();
425	        }
426	        return this.pets;
427	    }
428	
429	    protected void setPetsInternal(Set<Pet> pets) {
430	        this.pets = pets;
431	    }
432	
433	    public List<Pet> getPets() {
434	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
435	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
436	        return Collections.unmodifiableList(sortedPets);
437	    }
438	
439	    public void setPets(List<Pet> pets) {
440	        this.pets = new HashSet<>(pets);
441	    }
442	
443	    public void addPet(Pet pet) {
444	        getPetsInternal().add(pet);
445	        pet.setOwner(this);
446	    }
447	
448	    /**
449	     * Return the Pet with the given name, or null if none found for this Owner.
450	     *
451	     * @param name to test
452	     * @return true if pet name is already in use
453	     */
454	    public Pet getPet(String name) {
455	        return getPet(name, false);
456	    }
457	
458	    /**
459	     * Return the Pet with the given name, or null if none found for this Owner.
460	     *
461	     * @param name to test
462	     * @return true if pet name is already in use
463	     */
464	    public Pet getPet(String name, boolean ignoreNew) {
465	        name = name.toLowerCase();
466	        for (Pet pet : getPetsInternal()) {
467	            if (!ignoreNew || !pet.isNew()) {
468	                String compName = pet.getName();
469	                compName = compName.toLowerCase();
470	                if (compName.equals(name)) {
471	                    return pet;
472	                }
473	            }
474	        }
475	        return null;
476	    }
477	
478	    public Pet getPet(Integer petId) {
479	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
480	    }
481	
482	    @Override
483	    public String toString() {
484	        return new ToStringCreator(this)
485	
486	            .append("id", this.getId())
487	            .append("new", this.isNew())
488	            .append("lastName", this.getLastName())
489	            .append("firstName", this.getFirstName())
490	            .append("address", this.address)
491	            .append("city", this.city)
492	            .append("telephone", this.telephone)
493	            .toString();
494	    }
495	}
